package ama.transcript;
import java.util.*;import java.lang.reflect.*;import ama.contract.MinutesContracts.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class Task11FrozenFinalProjectionTest {
 static final String SET="12345678-1234-4234-8234-123456789abc",ELEMENT="12345678-1234-4234-8234-123456789abd",OTHER="12345678-1234-4234-8234-123456789abe";
 FullRow row(Table table,Map<String,Object> values){var cells=new ArrayList<Cell>();for(var col:table.columns()){var v=values.get(col.name());cells.add(v==null?new NullCell():col.kind()==CellKind.UINT?new UIntCell(((Number)v).longValue()):new TextCell(v.toString()));}return new FullRow(table,cells);}
 @SuppressWarnings("unchecked") Map<String,Object> elements(List<FullRow> rows)throws Exception{var c=assertDoesNotThrow(()->Class.forName("ama.transcript.FrozenFinalProjection"),"Final detail must project frozen structured rows");var m=c.getDeclaredMethod("elements",List.class,String.class);m.setAccessible(true);return (Map<String,Object>)m.invoke(null,rows,SET);}
 @Test void exactFrozenSetContainsAcceptedActionTupleAndNeverCurrentOtherSet()throws Exception {var rows=List.of(row(Table.MINUTES_ELEMENT,Map.of("id",ELEMENT,"set_id",SET,"category","ACTION","ordinal",0L,"body","Frozen action","support_state","SUPPORTED")),row(Table.ACTION_ITEM,Map.of("element_id",ELEMENT,"owner_display","Original owner","due_on","2026-10-26")),row(Table.MINUTES_ELEMENT,Map.of("id",OTHER,"set_id",OTHER,"category","ACTION","ordinal",0L,"body","Changed current action","support_state","SUPPORTED")));var actions=(List<?>)elements(rows).get("ACTION");assertEquals(1,actions.size());var action=(Map<?,?>)actions.getFirst();assertEquals("Frozen action",action.get("body"));assertEquals("Original owner",((Map<?,?>)action.get("action")).get("owner_display"));assertEquals("2026-10-26",((Map<?,?>)action.get("action")).get("due_on"));assertFalse(action.containsKey("suggestion"));}
 @Test void frozenElementsAreOrderedAndContainEveryDeclaredCategory()throws Exception {var rows=List.of(row(Table.MINUTES_ELEMENT,Map.of("id",OTHER,"set_id",SET,"category","CONCLUSION","ordinal",2L,"body","second","support_state","PARTIAL")),row(Table.MINUTES_ELEMENT,Map.of("id",ELEMENT,"set_id",SET,"category","CONCLUSION","ordinal",1L,"body","first","support_state","SUPPORTED")));var value=elements(rows);assertEquals(Category.values().length,value.size());assertEquals("first",((Map<?,?>)((List<?>)value.get("CONCLUSION")).getFirst()).get("body"));}
}
